```c
#include <stdio.h>

typedef long long ll;

static ll bitA[200005];
static ll bitB[200005];
static int N;

void add(ll *bit, int idx, ll val) {
    while (idx <= N) {
        bit[idx] += val;
        idx += idx & -idx;
    }
}

ll query(ll *bit, int idx) {
    ll res = 0;
    while (idx > 0) {
        res += bit[idx];
        idx -= idx & -idx;
    }
    return res;
}

void range_add(ll *bit, int l, int r, ll val) {
    if (l > r) return;
    add(bit, l, val);
    if (r + 1 <= N) add(bit, r + 1, -val);
}

int main(void) {
    int M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    for (int k = 0; k < M; k++) {
        int type;
        scanf("%d", &type);

        if (type == 3) {
            int i;
            scanf("%d", &i);

            ll a = query(bitA, i);
            ll b = query(bitB, i);

            printf("%lld\n", a * (ll)i + b);
        } else {
            int i, v;
            scanf("%d %d", &i, &v);

            if (type == 1) {
                int l = i;
                int r = i + v - 1;
                if (r > N) r = N;

                range_add(bitA, l, r, -1);
                range_add(bitB, l, r, (ll)v + i);
            } else {
                int l = i - v + 1;
                if (l < 1) l = 1;
                int r = i;

                range_add(bitA, l, r, 1);
                range_add(bitB, l, r, (ll)v - i);
            }
        }
    }

    return 0;
}
```

